package net.civeira.phylax.feature.observe.observedsource.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.gateway.ObservedSourceCursor;
import net.civeira.phylax.feature.observe.observedsource.domain.gateway.ObservedSourceFilter;

class ObservedSourceSlider extends Slider<ObservedSource> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedSourceCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedSourceFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ObservedSourceFilter, ObservedSourceCursor, Iterator<ObservedSource>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ObservedSourceSlider(final Iterator<ObservedSource> multi, final int limit,
      final BiFunction<ObservedSourceFilter, ObservedSourceCursor, Iterator<ObservedSource>> gateway,
      final ObservedSourceFilter filter, final ObservedSourceCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param observedSources
   * @param limit
   * @return
   */
  @Override
  public Iterator<ObservedSource> next(List<ObservedSource> observedSources, int limit) {
    ObservedSource last = observedSources.get(observedSources.size() - 1);
    ObservedSourceCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
